def solve(g, sep, newc=2):
    h,w=len(g),len(g[0])
    rows={i for i in range(h) if all(v==sep for v in g[i])}
    cols={j for j in range(w) if all(g[i][j]==sep for i in range(h))}
    return [[newc if (i in rows or j in cols) else v for j,v in enumerate(row)] for i,row in enumerate(g)]
print(solve(G['Demo pair 1 input'],0)==G['Demo pair 1 output'])
import json
res=solve(G['Test input'],6)
print(json.dumps(res))
